document.addEventListener("DOMContentLoaded",()=>{const e=document.getElementById("orderBtn"),t=document.getElementById("copyToast");let o=null;e.addEventListener("click",async()=>{const n=e.querySelector("span");if(!n)return;const c=n.textContent.trim();try{if(navigator.clipboard&&window.isSecureContext)await navigator.clipboard.writeText(c);else{const e=document.createElement("textarea");e.value=c,e.style.position="fixed",e.style.opacity="0",document.body.appendChild(e),e.select(),document.execCommand("copy"),document.body.removeChild(e)}t.classList.add("show"),o&&clearTimeout(o),o=setTimeout(()=>{t.classList.remove("show")},2e3)}catch(e){console.error("Не вдалося скопіювати:",e)}})});